export const generatedNonGoals: GeneratedNonGoal[] = [
  {
    lead: "A graphical editor",
    why: "The caller here is an agent in a terminal, so a surface only a person can operate is one the agent cannot use. A local page where a person looks and answers is not an editor: it edits nothing, and its one write is the verdict call an agent would make.",
  },
  {
    lead: "Replacing Blender, Godot or the generative service",
    why: "Those three already do the work; what is missing is the loop around them, so this orchestrates and measures and never re-implements a renderer, an engine or a mesh generator.",
  },
  {
    lead: "Spending money on the agent's own judgement",
    why: "A fetch draws on a real balance, so the ceiling is a person's to set and the plugin's job is to make a spend bounded and visible, never to decide one is worth it.",
  },
  {
    lead: "One project's palette, rig or paths compiled in",
    why: "Cottony is the first consumer and not the specification, so anything it needs that a second project would not is configuration, and a default that cannot be overridden is a defect.",
  },
  {
    lead: "A hosted service or an account to sign into",
    why: "Everything runs on the developer's machine against files in their own repository, because a plugin that needs an account is one that fails on the day the account does.",
  },
  {
    lead: "An agent accepting or rejecting its own look",
    why: "A look, a sound, a line a character says and how hard a level feels are each what a person agreed to, so an agent that can write the verdict on its own run turns the one check the loop cannot automate into one more number it tunes.",
  },
  {
    lead: "One genre's level format built in",
    why: "A match-3 level is three numbers and a shooter's is a spawn timeline, so polyweave checks, compiles and measures a level through what the project declares, and a schema that assumes a genre fails the next game; PW205 exists to catch that.",
  },
  {
    lead: "Writing a game's story for it",
    why: "A world is a person's authorship, so polyweave holds what the game shows to the world a person declared and routes a line's tone to their verdict, and never invents the canon it then checks against.",
  },
];

